import{c as a,Q as s,j as t,m as i}from"./chunks/framework.W-g_WCNV.js";const u=JSON.parse(`{"title":"Caddy forward_auth","description":"Protect any site with GateKeeper using Caddy's forward_auth directive.","frontmatter":{"title":"Caddy forward_auth","description":"Protect any site with GateKeeper using Caddy's forward_auth directive."},"headers":[],"relativePath":"integrations/caddy.md","filePath":"integrations/caddy.md"}`),n={name:"integrations/caddy.md"};function p(o,e,r,l,d,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<p>Caddy&#39;s <code>forward_auth</code> directive sends each incoming request to an authentication service before proxying it. If GateKeeper responds 200 the request proceeds. Any other status code causes Caddy to follow the redirect returned by GateKeeper, sending the browser to the login page.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>A browser requests <code>app.example.com</code>.</li><li>Caddy sends a <code>GET /auth/verify</code> subrequest to GateKeeper, passing the session cookie.</li><li>GateKeeper returns 200 with <code>X-Auth-User</code>, <code>X-Auth-Email</code>, and <code>X-Auth-Groups</code> headers.</li><li>Caddy copies those headers into the upstream request and proxies it.</li><li>If the session is invalid, GateKeeper returns 401 with a <code>Location</code> header. Caddy redirects the browser to the GateKeeper login page.</li></ol><h2 id="caddyfile" tabindex="-1">Caddyfile <a class="header-anchor" href="#caddyfile" aria-label="Permalink to &quot;Caddyfile&quot;">​</a></h2><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># GateKeeper</span></span>
<span class="line"><span>auth.example.com {</span></span>
<span class="line"><span>    reverse_proxy localhost:8080</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Protected app</span></span>
<span class="line"><span>app.example.com {</span></span>
<span class="line"><span>    forward_auth localhost:8080 {</span></span>
<span class="line"><span>        uri /auth/verify</span></span>
<span class="line"><span>        copy_headers X-Auth-User X-Auth-Email X-Auth-Groups</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    reverse_proxy localhost:8081</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Replace <code>auth.example.com</code> with your GateKeeper <code>BASE_URL</code> and <code>app.example.com</code> with the domain you want to protect. The <code>forward_auth</code> block targets GateKeeper directly by address; <code>uri</code> specifies the verify path.</p><h2 id="access-policies" tabindex="-1">Access policies <a class="header-anchor" href="#access-policies" aria-label="Permalink to &quot;Access policies&quot;">​</a></h2><p>Append a <code>policy</code> query parameter to enforce a named policy. Only users in that policy are allowed through; everyone else gets a 403.</p><div class="language-caddy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">caddy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app.example.com {</span></span>
<span class="line"><span>    forward_auth localhost:8080 {</span></span>
<span class="line"><span>        uri /auth/verify?policy=my-policy</span></span>
<span class="line"><span>        copy_headers X-Auth-User X-Auth-Email X-Auth-Groups</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    reverse_proxy localhost:8081</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Create and manage policies from the <a href="/admin/policies.html">Access policies</a> page in the admin UI.</p><h2 id="identity-headers" tabindex="-1">Identity headers <a class="header-anchor" href="#identity-headers" aria-label="Permalink to &quot;Identity headers&quot;">​</a></h2><p>GateKeeper sets the following response headers on a successful 200:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>X-Auth-User</code></td><td>The user&#39;s internal UUID</td></tr><tr><td><code>X-Auth-Email</code></td><td>The user&#39;s email address</td></tr><tr><td><code>X-Auth-Groups</code></td><td>Comma-separated group names (omitted when the user has no groups)</td></tr></tbody></table><p>The <code>copy_headers</code> directive forwards these to your backend automatically.</p><h2 id="logout" tabindex="-1">Logout <a class="header-anchor" href="#logout" aria-label="Permalink to &quot;Logout&quot;">​</a></h2><p>Add a logout link in your app that posts to GateKeeper&#39;s logout endpoint:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> method</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;POST&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com/logout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;submit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Sign out&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">form</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="protecting-gatekeeper-itself" tabindex="-1">Protecting GateKeeper itself <a class="header-anchor" href="#protecting-gatekeeper-itself" aria-label="Permalink to &quot;Protecting GateKeeper itself&quot;">​</a></h2><p>Do not apply <code>forward_auth</code> to the GateKeeper site block. Doing so creates a loop where the auth server requires authentication to serve the login page.</p>`,19)])])}const k=a(n,[["render",p]]);export{u as __pageData,k as default};
